public class PartitionerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.Map<Boolean, java.util.List<Integer>> m =
                    Partitioner.evensAndOdds(java.util.List.of(1, 2, 3, 4, 5, 6));
            check("evens of 1..6", "[2, 4, 6]", String.valueOf(m.get(true)));
            check("odds of 1..6", "[1, 3, 5]", String.valueOf(m.get(false)));
            check("exactly the two Boolean keys", 2, m.size());

            java.util.Map<Boolean, java.util.List<Integer>> mixed =
                    Partitioner.evensAndOdds(java.util.List.of(0, -3, -4, 7));
            check("zero and negatives partition as evens", "[0, -4]", String.valueOf(mixed.get(true)));
            check("negative odds land on the false side", "[-3, 7]", String.valueOf(mixed.get(false)));

            java.util.Map<Boolean, java.util.List<Integer>> allOdd =
                    Partitioner.evensAndOdds(java.util.List.of(1, 3));
            check("no evens -> true key still present with []", "[]", String.valueOf(allOdd.get(true)));

            java.util.Map<Boolean, java.util.List<Integer>> none =
                    Partitioner.evensAndOdds(java.util.List.of());
            check("empty input still yields both keys", 2, none.size());
            check("empty input -> empty odds list", "[]", String.valueOf(none.get(false)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  evensAndOdds usage -- threw " + e.getClass().getSimpleName());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

