public class Partitioner {

    public static java.util.Map<Boolean, java.util.List<Integer>> evensAndOdds(java.util.List<Integer> nums) {
        return nums.stream()
                .collect(java.util.stream.Collectors.partitioningBy(n -> n % 2 == 0));
    }
}
